SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Alinna Vargas is a Dominican merengue and tropical artist from Santo Domingo whose voice and presence have contributed to the newer generation of Dominican popular music. Working in the festive, rhythmically driven traditions of merengue and tropical, she brings a contemporary sensibility to sounds with deep roots in Dominican culture. As a female artist in the merengue world, Alinna Vargas participates in the tradition of Dominican women who have claimed space in a genre that has always had its most visible stars on both sides of the gender divide, from the days of Las Chicas del Can through the present generation. Her work adds to the ongoing vitality of Dominican popular music.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'alinna-vargas';
UPDATE artists SET bio_en = 'Alinna Vargas is a Dominican merengue and tropical artist from Santo Domingo whose voice and presence have contributed to the newer generation of Dominican popular music. Working in the festive, rhythmically driven traditions of merengue and tropical, she brings a contemporary sensibility to sounds with deep roots in Dominican culture. As a female artist in the merengue world, Alinna Vargas participates in the tradition of Dominican women who have claimed space in a genre that has always had its most visible stars on both sides of the gender divide, from the days of Las Chicas del Can through the present generation. Her work adds to the ongoing vitality of Dominican popular music.', bio_es = NULL WHERE slug = 'alinna-vargas';

